// Кейс: .qa/tests/i18n/I18N-001.md · план: .qa/e2e-app/specs/app.md (1.4)
// Раскладка RTL по координатам: заголовки справа, «חזרה» справа, «בית» правее «חשבון»; английских подписей нет.
// Язык телефона тест не меняет: главный прогон — при English (или русском) языке iPhone, выставленном вручную.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab, tabEl, TABS } from '../../lib/banci.mjs';

export const name = 'Иврит и RTL при любом языке телефона: таб-бар справа налево, заголовки и «חזרה» справа #f7167929 @iphone @app @prod-safe';

const ENGLISH = ['Home', 'History', 'Children', 'Account', 'Sign in', 'Create account', 'Back', 'Emergency', 'Devices'];

/** Заголовок экрана — самый верхний StaticText с этим текстом (вкладка с тем же текстом ниже). */
async function title(app, text) {
  const els = await app.findAll(by.exact(text, 'StaticText'));
  assert(els.length, `заголовок «${text}» виден`);
  const rects = await Promise.all(els.map((e) => e.rect()));
  return rects.reduce((a, b) => (b.y < a.y ? b : a));
}

async function noEnglish(app, where) {
  for (const w of ENGLISH) assert(!(await app.exists(by.exact(w))), `на «${where}» нет английской подписи «${w}»`);
}

export default async function (app) {
  const { width: W } = await app.windowRect();

  // 1. «בית»: таб-бар — 4 вкладки на иврите, порядок справа налево.
  await onHome(app);
  const rects = {};
  for (const t of TABS) rects[t] = (await tabEl(app, t)).rect;
  const cx = (r) => r.x + r.width / 2;
  assert(cx(rects['בית']) > cx(rects['חשבון']), `«בית» правее «חשבון» (x ${Math.round(cx(rects['בית']))} > ${Math.round(cx(rects['חשבון']))})`);
  assert(cx(rects['בית']) > W / 2, '«בית» в правой половине таб-бара');
  assert(cx(rects['חשבון']) < W / 2, '«חשבון» в левой половине таб-бара');
  await noEnglish(app, 'בית');

  // 2. «היסטוריה» и «חשבון»: заголовок прижат вправо.
  for (const t of ['היסטוריה', 'חשבון']) {
    await openTab(app, t);
    const r = await title(app, t);
    assert(cx(r) > W / 2 && r.x + r.width > W * 0.75, `заголовок «${t}» справа (x=${Math.round(r.x)}, w=${Math.round(r.width)}, экран ${W})`);
    await noEnglish(app, t);
  }

  // 3. «חשבון» → «מכשירים»: кнопка «חזרה» справа.
  const devices = await app.scrollTo(by.begins('מכשירים'), { what: 'пункт «מכשירים» в «חשבון»' });
  await devices.click();
  const back = await app.waitFor(by.exact('חזרה'), { what: 'кнопка «חזרה» на «מכשירים»' });
  const br = await back.rect();
  assert(cx(br) > W / 2, `«חזרה» в правой половине экрана (x=${Math.round(br.x)}, экран ${W})`);
  await noEnglish(app, 'מכשירים');
  await back.click();
  await app.waitFor(by.begins('מכשירים'), { what: 'возврат на «חשבון»' });
}
